from threading import Lock
from typing import Any, Dict, List, Optional, Set, Tuple

from codx.junior.globals import CODX_JUNIOR_API_BACKGROUND
from codx.junior.model.persona import Persona, PersonaTrigger
from codx.junior.personas.persona_manager import (
    personas_for_project,
    resolve_persona_profile,
)
from codx.junior.personas.task_handlers import TaskContext, get_handler
from codx.junior.project.project_discover import find_all_projects, find_project_by_id
from codx.junior.settings import CODXJuniorSettings

logger = logging.getLogger(__name__)

# Fire-and-forget executor for event-triggered persona jobs.
_EVENT_EXECUTOR = ThreadPoolExecutor(max_workers=5, thread_name_prefix="PersonaEvent")
_QUEUED: Set[Tuple] = set()
_QUEUE_LOCK = Lock()


def _profile_is_autonomous(profile) -> bool:
    autonomy = getattr(profile, "autonomy", None)
    return bool(autonomy and autonomy.enabled)


async def run_trigger(
    project: CODXJuniorSettings,
    persona: Persona,
    trigger: PersonaTrigger,
    event: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Run a single persona trigger against *project*.

    Resolves the persona profile, checks its autonomy flag and dispatches to
    the registered task handler named by ``trigger.task``.
    """
    profile = resolve_persona_profile(project=project, persona=persona)
    if profile is None:
        logger.warning(
            "Persona '%s' profile '%s' not found for project '%s'",
            persona.name,
            persona.profile,
            project.project_name,
        )
        return {
            "project": project.project_name,
            "persona": persona.name,
            "error": f"profile '{persona.profile}' not found",
        }

    if not _profile_is_autonomous(profile):
        logger.info(
            "Profile '%s' is not autonomous; skipping persona '%s' for '%s'",
            profile.name,
            persona.name,
            project.project_name,
        )
        return {
            "project": project.project_name,
            "persona": persona.name,
            "skipped": "profile is not autonomous",
        }

    handler = get_handler(trigger.task or "prompt")
    if handler is None:
        return {
            "project": project.project_name,
            "persona": persona.name,
            "error": f"unknown task handler '{trigger.task}'",
        }

    return await handler.run(
        TaskContext(
            project=project,
            persona=persona,
            profile=profile,
            trigger=trigger,
            event=event,
        )
    )


def run_trigger_sync(
    project: CODXJuniorSettings,
    persona: Persona,
    trigger: PersonaTrigger,
    event: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Synchronous wrapper for ``run_trigger`` (own event loop per thread)."""
    return asyncio.run(run_trigger(project, persona, trigger, event))


def run_manual_trigger(
    project: CODXJuniorSettings,
    persona: Persona,
    trigger: Optional[PersonaTrigger] = None,
    event: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Run a persona's manual trigger (optionally the first one found)."""
    if trigger is None:
        trigger = next((t for t in persona.triggers if t.type == "manual"), None)
    if trigger is None:
        return {"project": project.project_name, "persona": persona.name, "error": "no manual trigger"}
    return run_trigger_sync(project, persona, trigger, event)


def _enqueue(key: Tuple, fn, *args) -> bool:
    """Deduplicate and fire-and-forget a persona job."""
    with _QUEUE_LOCK:
        if key in _QUEUED:
            return False
        _QUEUED.add(key)

    def run() -> None:
        try:
            fn(*args)
        except Exception as ex:
            logger.exception("Persona event job failed: %s", ex)
        finally:
            with _QUEUE_LOCK:
                _QUEUED.discard(key)

    _EVENT_EXECUTOR.submit(run)
    return True


def dispatch_persona_event(
    event_name: str, payload: Optional[Dict[str, Any]] = None
) -> None:
    """
    Dispatch an event to every persona with a matching event trigger.

    The job is enqueued on a background executor and deduplicated by
    ``(event_name, project_id, persona, task, chat_id)`` so repeated saves do
    not flood the executor.
    """
    if not CODX_JUNIOR_API_BACKGROUND:
        return

    payload = payload or {}
    project_id = payload.get("project_id")

    projects: List[CODXJuniorSettings] = []
    if project_id:
        project = find_project_by_id(project_id)
        if project:
            projects = [project]
    else:
        all_projects = find_all_projects()
        projects = list(all_projects.values()) if all_projects else []

    for project in projects:
        for persona in personas_for_project(project):
            for trigger in persona.triggers:
                if trigger.type != "event" or trigger.event != event_name:
                    continue

                key = (
                    event_name,
                    project.project_id,
                    persona.name,
                    trigger.task,
                    payload.get("chat_id"),
                )
                _enqueue(key, run_trigger_sync, project, persona, trigger, payload)

